        score -= (open_bins_count as f64) * 0.8;
    }

    // Late‑stream adjustment: if many bins are open, favor opening a new one
    if step_index > total_items * 3 / 4 {
        if open_bins_count > total_items / 30 {
            if bin_residual != bin_capacity {
                score += 4.0;
            } else {
                score -= 8.0;
            }
        }
    }

    // Periodic tweak: every 7 steps, slightly favor bins whose residual is near the mean
    if step_index % 7 == 0 {
        score -= dev * 5.0;
    }

    score
}
